  ],
  "dataModelSchema": {
    "sleep": {
      "durationText": {
        "type": "string",
        "description": "今日睡眠总时长展示文本。",
        "sampleValue": "7h 12m"
      },
      "caption": {
        "type": "string",
        "description": "主睡眠时长的短说明。",
        "sampleValue": "睡眠时长"
      },
      "progressValue": {
        "type": "number",
        "description": "今日睡眠目标完成进度值。",
        "sampleValue": 72
      },
      "progressTotal": {
        "type": "number",
        "description": "今日睡眠目标完成进度总量。",
        "sampleValue": 80
      },
      "weeklyShortageLabel": {
        "type": "string",
        "description": "本周睡眠不足提醒标题。",
        "sampleValue": "本周睡眠不足"
      },
      "weeklyShortageText": {
        "type": "string",
        "description": "本周睡眠不足超出阈值的警告文案。",
        "sampleValue": "已超出1小时"
      }
    },
    "weekend": {
      "label": {
        "type": "string",
        "description": "周末倒计时标题。",
        "sampleValue": "距离周末"
      },
      "valueText": {
        "type": "string",
        "description": "距离周末的剩余天数展示文本。",
        "sampleValue": "2天"
      }
    },
    "data": {
      "weather": {
        "current": {
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "阴"
          },
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "18°C"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合今日阴天或多云天气面板。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合距离周末的倒计时面板。"
    },
    {
      "src": "resources/base/media/icon_remind.png",
      "description": "提醒图标，适合睡眠不足警告面板。"
    }
  ]
}

